	runes := []rune(fitted)
	cut := c.Cut(item)
	switch {
	case cut < 0:
		cut = 0
	case cut > len(runes):
		cut = len(runes)
	}
	head := " " + string(runes[:cut])
	tail := string(runes[cut:]) + " "
	return m.runStyle(c.Style, item, selected).Render(head) + m.runStyle(c.TailStyle, item, selected).Render(tail)
}

